// Validate required inputs
const { itemId, dropboxPath, fileName, mondayColumnId, mondayApiToken, dropboxAccessToken } = $input.first().json;

const missing = [];
if (!itemId) missing.push('itemId');
if (!dropboxPath) missing.push('dropboxPath');
if (!fileName) missing.push('fileName');
if (!mondayColumnId) missing.push('mondayColumnId');
if (!mondayApiToken) missing.push('mondayApiToken');
if (!dropboxAccessToken) missing.push('dropboxAccessToken');

if (missing.length > 0) {
  throw new Error(`Missing required inputs: ${missing.join(', ')}`);
}

// Determine MIME type from file extension
const ext = fileName.split('.').pop().toLowerCase();
const mimeTypes = {
  xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  xls: 'application/vnd.ms-excel',
  pdf: 'application/pdf',
  docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  doc: 'application/msword',
  pptx: 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
  csv: 'text/csv'
};
const mimeType = mimeTypes[ext] || 'application/octet-stream';

return [{ json: { itemId, dropboxPath, fileName, mondayColumnId, mondayApiToken, dropboxAccessToken, mimeType } }];

// Merge temp link with upstream data
const upstream = $('Validate & Prepare Inputs').first().json;
const { link } = $input.first().json;

if (!link) {
  throw new Error('Dropbox did not return a temporary download link. Check that the file path is correct and the token has files.content.read permission.');
}

return [{ json: { ...upstream, dropboxTempLink: link } }];

// Rename the binary data key to 'uploadFile' for the Monday upload step
const context = $('Merge Link With Context').first().json;
const binaryData = $input.first().binary;

if (!binaryData || !binaryData.fileData) {
  throw new Error('File download from Dropbox returned no binary data.');
}

// Rename binary key
const renamedBinary = { uploadFile: { ...binaryData.fileData, fileName: context.fileName, mimeType: context.mimeType } };

return [{ json: context, binary: renamedBinary }];

// Build success response
const uploadResult = $input.first().json;
const context = $('Rename Binary Key').first().json;

if (uploadResult.errors) {
  throw new Error(`Monday.com API error: ${JSON.stringify(uploadResult.errors)}`);
}

const mondayFileId = uploadResult?.data?.add_file_to_column?.id;

return [{
  json: {
    success: true,
    mondayFileId,
    itemId: context.itemId,
    columnId: context.mondayColumnId,
    fileName: context.fileName,
    dropboxPath: context.dropboxPath,
    message: `File '${context.fileName}' successfully uploaded to Monday.com item ${context.itemId}, column '${context.mondayColumnId}'. File ID: ${mondayFileId}.`
  }
}];
